"use client";
import { useEffect, useRef, useState } from "react";
import { ChevronRight } from "lucide-react";
import SectionLayout from "./SectionLayout";
import ProductCard from "./ProductCard";
import data, { getProducts } from "@/lib/data";

const START = 8 * 3600 + 42 * 60 + 15;
const pad = (n) => String(n).padStart(2, "0");

function Countdown() {
  const [left, setLeft] = useState(START);
  useEffect(() => {
    const t = setInterval(() => setLeft((s) => (s <= 1 ? 24 * 3600 : s - 1)), 1000);
    return () => clearInterval(t);
  }, []);
  const parts = [
    [pad(Math.floor(left / 3600)), "Hours"],
    [pad(Math.floor((left % 3600) / 60)), "Mins"],
    [pad(left % 60), "Secs"],
  ];
  return (
    <div className="mt-3 flex items-center gap-1" role="timer" aria-label="Time left for today's deals">
      {parts.map(([v, l], idx) => (
        <div key={l} className="flex items-center gap-1">
          <div className="w-[52px] rounded-md bg-forest py-1 text-center text-white">
            <div className="font-serif text-xl font-semibold leading-none">{v}</div>
            <div className="mt-0.5 text-[10px] font-medium">{l}</div>
          </div>
          {idx < 2 && <span className="font-bold text-forest">.</span>}
        </div>
      ))}
    </div>
  );
}

export default function DealsOfDay() {
  const deals = getProducts(data.dealIds);
  const rail = useRef(null);
  return (
    <SectionLayout title="Deals of the Day" subtitle="Grab these amazing offers!" aside={<Countdown />} asideWidth="230px" className="mt-4">
      <div className="relative flex items-center gap-2">
        <div ref={rail} className="no-scrollbar flex flex-1 snap-x gap-px overflow-x-auto rounded-lg bg-white/60 shadow-card">
          {deals.map((p) => (
            <div key={p.id} className="min-w-[270px] flex-1 snap-start border-r border-ink/5 last:border-r-0 lg:min-w-0">
              <ProductCard product={p} variant="deal" />
            </div>
          ))}
        </div>
        <button
          onClick={() => rail.current?.scrollBy({ left: 280, behavior: "smooth" })}
          aria-label="Scroll deals"
          className="hidden h-8 w-8 shrink-0 place-items-center rounded-full border border-ink/20 bg-white hover:bg-sage sm:grid lg:hidden"
        >
          <ChevronRight className="h-4 w-4" />
        </button>
        <button aria-hidden tabIndex={-1} className="hidden h-8 w-8 shrink-0 place-items-center rounded-full border border-ink/20 bg-white lg:grid">
          <ChevronRight className="h-4 w-4" />
        </button>
      </div>
    </SectionLayout>
  );
}
