"use client";
import { useEffect, useRef } from "react";

/** Adds `.in` when scrolled into view -> triggers CSS transition (section transition animation). */
export default function Reveal({ as: Tag = "div", v = "up", delay = 0, className = "", wipe = false, children, ...rest }) {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) { el.classList.add("in"); io.disconnect(); } },
      { threshold: 0.15, rootMargin: "0px 0px -8% 0px" }
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);
  return (
    <Tag ref={ref} data-v={v} style={{ "--d": `${delay}ms` }} className={`${wipe ? "wipe" : "reveal"} ${className}`} {...rest}>
      {children}
    </Tag>
  );
}
